<?php
declare(strict_types=1);
function hqoSchema(PDO $p):void
{
    $sql=(string)file_get_contents(dirname(__DIR__,2).'/migrations/089_hotel_quarantine_onward.sql');
    if($p->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'){foreach(explode(';',$sql)as$s)if(trim($s)!=='')$p->exec($s);return;}
    $ddl=substr($sql,0,strpos($sql,'DROP TRIGGER'));
    $ddl=preg_replace('/ CHARACTER SET ascii COLLATE ascii_bin/','',$ddl);
    $p->exec(str_replace([' ENGINE=InnoDB','LONGBLOB'],['','BLOB'],$ddl));
    foreach(['queue_update','queue_delete','receipt_insert','receipt_update','receipt_delete']as$n)$p->exec('DROP TRIGGER IF EXISTS hotel_quarantine_'.$n);
    $p->sqliteCreateFunction('concat_ws',static fn(...$v):string=>implode(array_shift($v),$v),-1);
    $p->sqliteCreateFunction('hotel_queue_session',static fn():string=>'unprivileged-fixture-session',0);
    $p->exec(<<<'SQL'
CREATE TRIGGER hotel_quarantine_queue_update BEFORE UPDATE ON hotel_work_queues WHEN (OLD.write_protocol='quarantine_v1' OR OLD.persistent_fence=1 OR NEW.persistent_fence=1) AND NOT (((NEW.queue_id IS OLD.queue_id) AND (NEW.project_key IS OLD.project_key) AND (NEW.admin_id IS OLD.admin_id) AND (NEW.oauth_connection_id IS OLD.oauth_connection_id) AND (NEW.mode IS OLD.mode) AND (NEW.batch_limit IS OLD.batch_limit) AND (NEW.start_country IS OLD.start_country) AND (NEW.initial_phase_counter IS OLD.initial_phase_counter) AND (NEW.phase_counter IS OLD.phase_counter) AND (NEW.baseline_sha256 IS OLD.baseline_sha256) AND (NEW.plan_sha256 IS OLD.plan_sha256) AND (NEW.stage_index IS OLD.stage_index) AND (NEW.state IS OLD.state) AND (NEW.claim_sha256 IS OLD.claim_sha256) AND (NEW.current_run_id IS OLD.current_run_id) AND (NEW.accepted_batches IS OLD.accepted_batches) AND (NEW.write_protocol IS OLD.write_protocol) AND (NEW.data_snapshot_sha256 IS OLD.data_snapshot_sha256) AND (NEW.persistent_fence IS OLD.persistent_fence)) OR (((NEW.queue_id IS OLD.queue_id) AND (NEW.project_key IS OLD.project_key) AND (NEW.admin_id IS OLD.admin_id) AND (NEW.oauth_connection_id IS OLD.oauth_connection_id) AND (NEW.mode IS OLD.mode) AND (NEW.batch_limit IS OLD.batch_limit) AND (NEW.start_country IS OLD.start_country) AND (NEW.initial_phase_counter IS OLD.initial_phase_counter) AND (NEW.baseline_sha256 IS OLD.baseline_sha256) AND (NEW.plan_sha256 IS OLD.plan_sha256) AND (NEW.write_protocol IS OLD.write_protocol) AND (NEW.data_snapshot_sha256 IS OLD.data_snapshot_sha256) AND (NEW.persistent_fence IS OLD.persistent_fence)) AND EXISTS(SELECT 1 FROM hotel_quarantine_intake_permits p JOIN hotel_work_receipts r ON r.queue_id=p.queue_id AND r.stage_id=p.stage_id AND r.receipt_sha256=p.receipt_sha256 WHERE p.queue_id=OLD.queue_id AND p.session_id=hotel_intake_session() AND p.stage_index=OLD.stage_index AND p.claim_sha256=OLD.claim_sha256 AND OLD.persistent_fence=0 AND OLD.state='claimed' AND OLD.current_run_id IS NULL AND OLD.mode='continuous' AND NEW.stage_index=OLD.stage_index+1 AND NEW.state='ready' AND NEW.claim_sha256 IS NULL AND NEW.current_run_id IS NULL AND NEW.accepted_batches=p.target_accepted AND p.target_accepted=OLD.accepted_batches+1 AND NEW.phase_counter=p.target_phase AND p.target_phase=1-OLD.phase_counter)) OR EXISTS(SELECT 1 FROM hotel_queue_write_permits p JOIN hotel_quarantine_adoptions a ON a.queue_id=p.queue_id WHERE p.queue_id=OLD.queue_id AND p.session_id=hotel_queue_session() AND p.old_sha256=SHA2(CONCAT_WS(CHAR(31),COALESCE(CAST(OLD.queue_id AS CHAR),'~'),COALESCE(CAST(OLD.project_key AS CHAR),'~'),COALESCE(CAST(OLD.admin_id AS CHAR),'~'),COALESCE(CAST(OLD.oauth_connection_id AS CHAR),'~'),COALESCE(CAST(OLD.mode AS CHAR),'~'),COALESCE(CAST(OLD.batch_limit AS CHAR),'~'),COALESCE(CAST(OLD.start_country AS CHAR),'~'),COALESCE(CAST(OLD.initial_phase_counter AS CHAR),'~'),COALESCE(CAST(OLD.phase_counter AS CHAR),'~'),COALESCE(CAST(OLD.baseline_sha256 AS CHAR),'~'),COALESCE(CAST(OLD.plan_sha256 AS CHAR),'~'),COALESCE(CAST(OLD.stage_index AS CHAR),'~'),COALESCE(CAST(OLD.state AS CHAR),'~'),COALESCE(CAST(OLD.claim_sha256 AS CHAR),'~'),COALESCE(CAST(OLD.current_run_id AS CHAR),'~'),COALESCE(CAST(OLD.accepted_batches AS CHAR),'~'),COALESCE(CAST(OLD.write_protocol AS CHAR),'~'),COALESCE(CAST(OLD.data_snapshot_sha256 AS CHAR),'~'),COALESCE(CAST(OLD.persistent_fence AS CHAR),'~')),256) AND p.new_sha256=SHA2(CONCAT_WS(CHAR(31),COALESCE(CAST(NEW.queue_id AS CHAR),'~'),COALESCE(CAST(NEW.project_key AS CHAR),'~'),COALESCE(CAST(NEW.admin_id AS CHAR),'~'),COALESCE(CAST(NEW.oauth_connection_id AS CHAR),'~'),COALESCE(CAST(NEW.mode AS CHAR),'~'),COALESCE(CAST(NEW.batch_limit AS CHAR),'~'),COALESCE(CAST(NEW.start_country AS CHAR),'~'),COALESCE(CAST(NEW.initial_phase_counter AS CHAR),'~'),COALESCE(CAST(NEW.phase_counter AS CHAR),'~'),COALESCE(CAST(NEW.baseline_sha256 AS CHAR),'~'),COALESCE(CAST(NEW.plan_sha256 AS CHAR),'~'),COALESCE(CAST(NEW.stage_index AS CHAR),'~'),COALESCE(CAST(NEW.state AS CHAR),'~'),COALESCE(CAST(NEW.claim_sha256 AS CHAR),'~'),COALESCE(CAST(NEW.current_run_id AS CHAR),'~'),COALESCE(CAST(NEW.accepted_batches AS CHAR),'~'),COALESCE(CAST(NEW.write_protocol AS CHAR),'~'),COALESCE(CAST(NEW.data_snapshot_sha256 AS CHAR),'~'),COALESCE(CAST(NEW.persistent_fence AS CHAR),'~')),256) AND NEW.persistent_fence=1 AND NEW.write_protocol='journal_v1')) BEGIN SELECT RAISE(ABORT,'database_quarantine'); END
SQL);
    $p->exec("CREATE TRIGGER hotel_quarantine_queue_delete BEFORE DELETE ON hotel_work_queues WHEN OLD.write_protocol='quarantine_v1' OR OLD.persistent_fence=1 BEGIN SELECT RAISE(ABORT,'database_quarantine'); END");
    $p->exec(<<<'SQL'
CREATE TRIGGER hotel_quarantine_receipt_insert BEFORE INSERT ON hotel_work_receipts WHEN EXISTS(SELECT 1 FROM hotel_work_queues WHERE queue_id=NEW.queue_id AND (write_protocol='quarantine_v1' OR persistent_fence=1)) AND NOT(EXISTS(SELECT 1 FROM hotel_quarantine_intake_permits p WHERE p.queue_id=NEW.queue_id AND p.session_id=hotel_intake_session() AND p.stage_id=NEW.stage_id AND p.stage_index=NEW.stage_index AND p.receipt_sha256=NEW.receipt_sha256 AND p.receipt_sha256=SHA2(NEW.receipt_json,256)) OR EXISTS(SELECT 1 FROM hotel_queue_write_permits p WHERE p.queue_id=NEW.queue_id AND p.session_id=hotel_queue_session() AND p.receipt_stage=NEW.stage_id AND p.receipt_index=NEW.stage_index AND p.receipt_sha256=NEW.receipt_sha256 AND p.receipt_sha256=SHA2(NEW.receipt_json,256))) BEGIN SELECT RAISE(ABORT,'database_quarantine'); END
SQL);
    foreach(['update'=>'OLD.queue_id,NEW.queue_id','delete'=>'OLD.queue_id']as$op=>$keys)$p->exec('CREATE TRIGGER hotel_quarantine_receipt_'.$op.' BEFORE '.strtoupper($op)." ON hotel_work_receipts WHEN EXISTS(SELECT 1 FROM hotel_work_queues WHERE queue_id IN(".$keys.") AND (write_protocol='quarantine_v1' OR persistent_fence=1)) BEGIN SELECT RAISE(ABORT,'database_quarantine'); END");
}

